-- 한글 경로 C:\검증
ALTER SERVICE MASTER KEY WITH OLD_ACCOUNT = 'CONTOSO\svc_old', OLD_PASSWORD = 'Old!Passw0rd';
ALTER SERVICE MASTER KEY WITH NEW_ACCOUNT = 'CONTOSO\svc_new', NEW_PASSWORD = 'N3w!Passw0rd';

-- 한글 경로 C:\검증
CREATE USER [ann@contoso.com] FROM EXTERNAL PROVIDER WITH OBJECT_ID = '6d9a3c1e-0000-4000-8000-000000000001';
CREATE USER [CONTOSO\Eve] WITH DEFAULT_LANGUAGE = English;
CREATE USER [CONTOSO\Ann] FOR LOGIN [CONTOSO\Ann] WITH DEFAULT_LANGUAGE = us_english;

-- 한글 경로 C:\검증
DECLARE @bits varbinary(max) = 0x4D5A90000300;
CREATE ASSEMBLY ExprAsm FROM @bits;

-- 한글 경로 C:\검증
CREATE AGGREGATE dbo.Concat (@value nvarchar(4000), @sep dbo.SepType) RETURNS nvarchar(max) EXTERNAL NAME StringUtils.[StringUtils.Concat];
CREATE AGGREGATE MergePoints (@p dbo.Point) RETURNS dbo.Point EXTERNAL NAME GeoUtils;
CREATE APPLICATION ROLE app_sales WITH PASSWORD = 'S3cure!pw', DEFAULT_SCHEMA = Sales;

-- 한글 경로 C:\검증
CREATE EVENT SESSION xe_db ON DATABASE ADD EVENT sqlserver.error_reported (WHERE severity > 10) ADD TARGET package0.ring_buffer (SET max_memory = 4096)
  WITH (EVENT_RETENTION_MODE = ALLOW_MULTIPLE_EVENT_LOSS, MAX_DISPATCH_LATENCY = INFINITE, MEMORY_PARTITION_MODE = PER_NODE, TRACK_CAUSALITY = OFF,
    STARTUP_STATE = ON, MAX_DURATION = 2 HOURS);
CREATE EVENT SESSION xe_waits ON SERVER ADD EVENT sqlos.wait_completed WITH (EVENT_RETENTION_MODE = NO_EVENT_LOSS, MEMORY_PARTITION_MODE = PER_CPU, MAX_DURATION = 30 SECONDS);

-- 한글 경로 C:\검증
CREATE RESOURCE POOL rp1 WITH (MIN_CPU_PERCENT = 10, MAX_CPU_PERCENT = 50, CAP_CPU_PERCENT = 80, AFFINITY SCHEDULER = AUTO, MIN_MEMORY_PERCENT = 5, MAX_MEMORY_PERCENT = 40, MIN_IOPS_PER_VOLUME = 20, MAX_IOPS_PER_VOLUME = 100);
CREATE RESOURCE POOL rp2 WITH (AFFINITY SCHEDULER = (0, 2 TO 3));
CREATE RESOURCE POOL rp3 WITH (AFFINITY NUMANODE = (0, 1 TO 2));

-- 한글 경로 C:\검증
CREATE WORKLOAD GROUP wg_reports WITH (IMPORTANCE = LOW, REQUEST_MAX_MEMORY_GRANT_PERCENT = 25, REQUEST_MAX_CPU_TIME_SEC = 60,
  REQUEST_MEMORY_GRANT_TIMEOUT_SEC = 30, MAX_DOP = 4, GROUP_MAX_REQUESTS = 10, GROUP_MAX_TEMPDB_DATA_MB = 1024) USING pool_reports, EXTERNAL epool_r;
CREATE WORKLOAD GROUP wg_adhoc WITH (IMPORTANCE = MEDIUM, GROUP_MAX_TEMPDB_DATA_PERCENT = 10) USING [default];
CREATE WORKLOAD GROUP wg_etl WITH (IMPORTANCE = HIGH);

-- 한글 경로 C:\검증
CREATE SPATIAL INDEX six1 ON db1.dbo.shapes (geom) USING GEOMETRY_AUTO_GRID WITH (BOUNDING_BOX = (0, 0, 500, 200), CELLS_PER_OBJECT = 64, PAD_INDEX = ON, FILLFACTOR = 80, SORT_IN_TEMPDB = ON, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = ON, DROP_EXISTING = ON, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, MAXDOP = 2, DATA_COMPRESSION = ROW) ON fg1;
CREATE SPATIAL INDEX six2 ON dbo.shapes (geom) USING GEOMETRY_GRID WITH (BOUNDING_BOX = (XMIN = 0, YMIN = 0, XMAX = 500, YMAX = 200), GRIDS = (LEVEL_1 = LOW, LEVEL_2 = MEDIUM, LEVEL_3 = HIGH, LEVEL_4 = HIGH), CELLS_PER_OBJECT = 16, PAD_INDEX = OFF, DATA_COMPRESSION = PAGE) ON "default";

-- 한글 경로 C:\검증
CREATE PRIMARY XML INDEX pxi_doc ON db1.dbo.Docs (Doc) WITH (PAD_INDEX = ON, FILLFACTOR = 80, SORT_IN_TEMPDB = ON, IGNORE_DUP_KEY = OFF,
  DROP_EXISTING = ON, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = OFF, MAXDOP = 2, XML_COMPRESSION = ON);
CREATE XML INDEX xi_value ON dbo.Docs (Doc) USING XML INDEX pxi_doc FOR VALUE;
CREATE XML INDEX xi_path ON Docs (Doc) USING XML INDEX pxi_doc FOR PATH;

-- 한글 경로 C:\검증
CREATE SPATIAL INDEX six1 ON db1.dbo.shapes (geom) USING GEOMETRY_AUTO_GRID WITH (BOUNDING_BOX = (0, 0, 500, 200), CELLS_PER_OBJECT = 64, PAD_INDEX = ON, FILLFACTOR = 80, SORT_IN_TEMPDB = ON, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = ON, DROP_EXISTING = ON, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, MAXDOP = 2, DATA_COMPRESSION = ROW) ON fg1;
CREATE SPATIAL INDEX six2 ON dbo.shapes (geom) USING GEOMETRY_GRID WITH (BOUNDING_BOX = (XMIN = 0, YMIN = 0, XMAX = 500, YMAX = 200), GRIDS = (LEVEL_1 = LOW, LEVEL_2 = MEDIUM, LEVEL_3 = HIGH, LEVEL_4 = HIGH), CELLS_PER_OBJECT = 16, PAD_INDEX = OFF, DATA_COMPRESSION = PAGE) ON "default";

-- 한글 경로 C:\검증
CREATE UNIQUE CLUSTERED INDEX ix1 ON db1.dbo.t1 (c1 ASC, c2 DESC) WITH (PAD_INDEX = ON, FILLFACTOR = 80, SORT_IN_TEMPDB = ON, IGNORE_DUP_KEY = ON, STATISTICS_NORECOMPUTE = ON, STATISTICS_INCREMENTAL = ON, DROP_EXISTING = ON, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = ON, MAXDOP = 4, DATA_COMPRESSION = ROW ON PARTITIONS (1, 3 TO 5)) ON ps1 (c1) FILESTREAM_ON fs_ps1;
CREATE NONCLUSTERED INDEX ix2 ON dbo.t1 (c3) INCLUDE (c4, c5) WITH (PAD_INDEX = OFF, DATA_COMPRESSION = PAGE, XML_COMPRESSION = ON ON PARTITIONS (2)) ON fg1 FILESTREAM_ON fs_fg1;
CREATE INDEX ix3 ON t1 (c1) WITH (DATA_COMPRESSION = NONE ON PARTITIONS (1 TO 2)) ON "default" FILESTREAM_ON "NULL";

-- 한글 경로 C:\검증
CREATE PRIMARY XML INDEX pxi_doc ON db1.dbo.Docs (Doc) WITH (PAD_INDEX = ON, FILLFACTOR = 80, SORT_IN_TEMPDB = ON, IGNORE_DUP_KEY = OFF,
  DROP_EXISTING = ON, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = OFF, MAXDOP = 2, XML_COMPRESSION = ON);
CREATE XML INDEX xi_value ON dbo.Docs (Doc) USING XML INDEX pxi_doc FOR VALUE;
CREATE XML INDEX xi_path ON Docs (Doc) USING XML INDEX pxi_doc FOR PATH;
